-- Isolated schema8 fixture generated by the unmodified build22 TaskStore.
BEGIN TRANSACTION;
CREATE TABLE capture_request(token TEXT PRIMARY KEY NOT NULL,occurrence_id TEXT NOT NULL REFERENCES reminder_occurrences(occurrence_id) ON DELETE CASCADE,source TEXT NOT NULL CHECK(source IN ('camera','image','screenshot','file')),capacity INTEGER NOT NULL CHECK(capacity BETWEEN 1 AND 6),created_at REAL NOT NULL,state INTEGER NOT NULL DEFAULT 0 CHECK(state BETWEEN 0 AND 2),pid INTEGER,payload BLOB,issue TEXT);
INSERT INTO "capture_request" VALUES('6235cffd-17bc-47c8-928b-1222e2bf6012','7219f445-4a56-4fe5-9d45-41880be96b1d','file',6,1792824318.4466128,0,NULL,NULL,NULL);
CREATE TABLE "reminder_checkins"(occurrence_id TEXT NOT NULL REFERENCES reminder_occurrences(occurrence_id) ON DELETE CASCADE,position INTEGER NOT NULL CHECK(typeof(position)='integer' AND position BETWEEN 0 AND 5),method TEXT NOT NULL CHECK(method IN ('camera','screenshot','image','file')),image BLOB NOT NULL CHECK(length(image)<=20971520 AND (method='file' OR length(image)>0)),created_at REAL NOT NULL,name TEXT,content_type TEXT,PRIMARY KEY(occurrence_id,position),CHECK(method!='file' OR (name IS NOT NULL AND length(name)>0 AND content_type IS NOT NULL AND length(content_type)>0)));
INSERT INTO "reminder_checkins" VALUES('209895ac-ded1-401c-895e-0728ac6d0659',0,'file',X'6F726967696E616C',1792824318.4466128,'proof.txt','public.plain-text');
CREATE TABLE reminder_occurrences (occurrence_id TEXT PRIMARY KEY NOT NULL, task_id TEXT NOT NULL REFERENCES tasks(task_id),scheduled_at REAL NOT NULL, triggered_at REAL, handled_at REAL, status TEXT NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','triggered','handled')),action TEXT,snooze_until REAL,created_at REAL NOT NULL,updated_at REAL NOT NULL,generation INTEGER NOT NULL DEFAULT 1,kind TEXT NOT NULL DEFAULT 'plan' CHECK(kind IN ('plan','deadline','both')),cycle_at REAL NOT NULL, defer_count INTEGER NOT NULL DEFAULT 0 CHECK(defer_count IN (0,1)), hold_reason TEXT CHECK(hold_reason IN ('snooze','screenshot')), hold_until REAL,UNIQUE(task_id,generation,kind,cycle_at),CHECK((status='pending' AND triggered_at IS NULL AND handled_at IS NULL) OR (status='triggered' AND triggered_at IS NOT NULL AND handled_at IS NULL) OR (status='handled' AND handled_at IS NOT NULL)));
