CREATE TABLE store_meta (singleton INTEGER PRIMARY KEY CHECK(singleton=1),schema_version INTEGER NOT NULL CHECK(schema_version>=0), data_revision INTEGER NOT NULL DEFAULT 0);
INSERT INTO "store_meta" VALUES(1,8,2);
CREATE TABLE task_lists (list_id TEXT PRIMARY KEY NOT NULL, title TEXT NOT NULL CHECK(length(title) BETWEEN 1 AND 1024),created_at REAL NOT NULL, updated_at REAL NOT NULL, deleted INTEGER NOT NULL DEFAULT 0 CHECK(deleted IN (0,1)));
INSERT INTO "task_lists" VALUES('00000000-0000-4000-8000-000000000001','我的任务',1792824319.0,1792824319.0,0);
CREATE TABLE tasks (task_id TEXT PRIMARY KEY NOT NULL, title TEXT NOT NULL CHECK(length(title) BETWEEN 1 AND 1024),notes TEXT NOT NULL DEFAULT '' CHECK(length(notes)<=8192), due_at REAL, timezone_id TEXT NOT NULL,recurrence_type TEXT NOT NULL DEFAULT 'none' CHECK(recurrence_type IN ('none','daily','weekly','monthly','yearly','custom')),recurrence_interval INTEGER NOT NULL DEFAULT 1 CHECK(typeof(recurrence_interval)='integer' AND recurrence_interval>=1),status TEXT NOT NULL DEFAULT 'needsAction' CHECK(status IN ('needsAction','completed')), snooze_until REAL,created_at REAL NOT NULL, updated_at REAL NOT NULL,list_id TEXT NOT NULL REFERENCES task_lists(list_id), parent_id TEXT REFERENCES tasks(task_id),position INTEGER NOT NULL DEFAULT 0 CHECK(typeof(position)='integer'), starred INTEGER NOT NULL DEFAULT 0 CHECK(starred IN (0,1)),schedule_kind TEXT NOT NULL DEFAULT 'none' CHECK(schedule_kind IN ('none','date','timed')),planned_duration REAL CHECK(planned_duration>0), deadline_at REAL,deadline_kind TEXT NOT NULL DEFAULT 'none' CHECK(deadline_kind IN ('none','date','timed')),recurrence_json TEXT NOT NULL DEFAULT '[]', completed_at REAL, deleted INTEGER NOT NULL DEFAULT 0 CHECK(deleted IN (0,1)), urgency INTEGER NOT NULL DEFAULT 0 CHECK(urgency BETWEEN 0 AND 3 AND typeof(urgency)='integer'), difficulty INTEGER NOT NULL DEFAULT 0 CHECK(difficulty BETWEEN 0 AND 3 AND typeof(difficulty)='integer'), reminder_version INTEGER NOT NULL DEFAULT 1, starred_at REAL,CHECK((status='completed' AND completed_at IS NOT NULL) OR (status='needsAction' AND completed_at IS NULL)),CHECK((schedule_kind='none' AND due_at IS NULL) OR (schedule_kind!='none' AND due_at IS NOT NULL)),CHECK((deadline_kind='none' AND deadline_at IS NULL) OR (deadline_kind!='none' AND deadline_at IS NOT NULL)),CHECK(parent_id IS NULL OR parent_id!=task_id));
INSERT INTO "tasks" VALUES('11f4b9a8-a565-41f6-b920-cbadb338740f','状态验收','',1792824318.4466128,'UTC','daily',1,'needsAction',NULL,1792824319.4467011,1792824319.4537859,'00000000-0000-4000-8000-000000000001',NULL,0,0,'timed',NULL,NULL,'none','["RRULE:FREQ=DAILY"]',NULL,0,0,0,1,NULL);
CREATE INDEX tasks_due ON tasks(deleted,status,due_at);
CREATE INDEX tasks_deadline ON tasks(deleted,status,deadline_at);
CREATE INDEX tasks_list ON tasks(list_id,parent_id,position);
CREATE INDEX occurrences_due ON reminder_occurrences(status,scheduled_at);
INSERT INTO reminder_occurrences(occurrence_id,task_id,scheduled_at,handled_at,status,action,snooze_until,created_at,updated_at,cycle_at) SELECT '00000000-0000-4000-8000-000000000010',task_id,scheduled_at+1000000,scheduled_at,'handled',NULL,NULL,created_at,updated_at,cycle_at+1000000 FROM reminder_occurrences LIMIT 1;
INSERT INTO reminder_occurrences(occurrence_id,task_id,scheduled_at,handled_at,status,action,snooze_until,created_at,updated_at,cycle_at) SELECT '00000000-0000-4000-8000-000000000011',task_id,scheduled_at+2000000,scheduled_at,'handled','snooze',scheduled_at+2000300,created_at,updated_at,cycle_at+2000000 FROM reminder_occurrences LIMIT 1;
COMMIT;
